INSERT INTO faqs (question, answer, sort_order) VALUES
  ('What do I need to open an account?', 'Usually a valid ID, a passport photograph, proof of address and your BVN. We''ll confirm the full list when you contact us.', 0),
  ('How long does a loan take?', 'It depends on the loan type and your documents. We''ll give you a clear timeline when you apply.', 1),
  ('Are there hidden charges?', 'No. All fees and interest are explained to you in writing before you sign anything.', 2),
  ('Will you ever ask for my PIN or password?', 'Never. We will never ask for your PIN, password or OTP by phone, SMS, email or WhatsApp. If anyone does, it''s a scam.', 3),
  ('Can I apply online?', 'You can start online with the Get Started form. An adviser will then guide you through the rest.', 4);
